21	
22	export type TaskDetailSheetProps = {
23	  task: ParsedTask | null;
24	  featureTitle?: string;
25	  repository?: string;
26	  nextAction?: string;
27	  onClose: () => void;
28	};
29	
30	export function TaskDetailSheet({
31	  task,
32	  featureTitle,
33	  repository,
34	  nextAction,
35	  onClose,
36	}: TaskDetailSheetProps) {
37	  const open = task !== null;
38	  const titleId = useId();
39	
40	  useEffect(() => {
41	    if (!open) return;
42	    const handleKey = (e: KeyboardEvent) => {
43	      if (e.key === "Escape") onClose();
44	    };
45	    document.addEventListener("keydown", handleKey);
46	    const previousOverflow = document.body.style.overflow;
47	    document.body.style.overflow = "hidden";
48	    return () => {
49	      document.removeEventListener("keydown", handleKey);
50	      document.body.style.overflow = previousOverflow;
51	    };
52	  }, [open, onClose]);
53	
54	  return (
55	    <div
56	      aria-hidden={!open}
57	      className={
58	        "pointer-events-none fixed inset-0 z-40 " +
59	        (open ? "pointer-events-auto" : "")
60	      }
61	    >
62	      <button
63	        type="button"
64	        aria-label="Close task detail"
65	        tabIndex={open ? 0 : -1}
66	        onClick={onClose}
67	        className={
68	          "absolute inset-0 cursor-default bg-black/50 transition-opacity duration-200 " +
69	          (open ? "opacity-100" : "opacity-0")
70	        }
71	      />
72	      <aside
73	        role="dialog"
74	        aria-modal="true"
75	        aria-labelledby={titleId}
76	        className={
77	          "absolute right-0 top-0 flex h-full w-full max-w-[576px] flex-col bg-bg shadow-xl transition-transform duration-200 ease-out " +
78	          (open ? "translate-x-0" : "translate-x-full")
79	        }
80	      >
81	        {task ? (
82	          <TaskDetailContents
83	            task={task}
84	            featureTitle={featureTitle}
85	            repository={repository}
86	            nextAction={nextAction}
87	            onClose={onClose}
88	            titleId={titleId}
89	          />
90	        ) : null}
91	      </aside>
92	    </div>
93	  );
94	}
95	
96	type ContentsProps = {
97	  task: ParsedTask;
98	  featureTitle: string | undefined;
99	  repository: string | undefined;
100	  nextAction: string | undefined;
101	  onClose: () => void;
102	  titleId: string;
103	};
104	
105	function TaskDetailContents({
106	  task,
107	  featureTitle,
108	  repository,
109	  nextAction,
110	  onClose,
111	  titleId,
112	}: ContentsProps) {
113	  const statusStyle = getStatusStyle(task.status);
114	  const lastUpdatedAt = task.execution?.last_updated_at;
115	
116	  return (
117	    <>
118	      <DetailHeader
119	        task={task}
120	        featureTitle={featureTitle}
121	        statusStyle={statusStyle}
122	        onClose={onClose}
123	        titleId={titleId}
124	      />
125	      <div className="flex-1 overflow-y-auto px-6 py-5">
126	        <MetadataSection
127	          task={task}
128	          repository={repository}
129	          nextAction={nextAction}
130	          lastUpdatedAt={lastUpdatedAt}
131	        />
132	        <PullRequestsSection task={task} />
133	        <TimelineSection log={task.log} />
134	      </div>
135	    </>
136	  );
137	}
138	
139	function DetailHeader({
140	  task,
141	  featureTitle,
142	  statusStyle,
143	  onClose,
144	  titleId,
145	}: {
146	  task: ParsedTask;
147	  featureTitle: string | undefined;
148	  statusStyle: StatusBadgeStyle;
149	  onClose: () => void;
150	  titleId: string;
151	}) {
152	  return (
153	    <header className="flex items-start justify-between gap-3 border-b border-border bg-surface px-6 py-4">
154	      <div className="flex min-w-0 flex-col gap-2">
155	        <div className="flex items-center gap-2">
156	          <span className="rounded-md bg-chip-bg px-2 py-0.5 text-xs font-semibold text-text-secondary">
157	            {task.id}
158	          </span>
159	          <span
160	            className={
161	              "rounded-md px-2 py-0.5 text-xs font-semibold uppercase tracking-wide " +
162	              statusStyle.bg +
163	              " " +
164	              statusStyle.text
165	            }
166	          >
167	            {formatStatusLabel(task.status)}
168	          </span>
169	        </div>
170	        <h2
171	          id={titleId}
172	          className="text-lg font-semibold leading-snug text-text-primary"
173	        >
174	          {task.title || task.id}
175	        </h2>
176	        {featureTitle ? (
177	          <p className="text-xs text-text-muted">{featureTitle}</p>
178	        ) : null}
179	      </div>
180	      <button
181	        type="button"
182	        onClick={onClose}
183	        aria-label="Close"
184	        className="shrink-0 rounded p-1 text-text-secondary transition-colors hover:bg-surface-subtle hover:text-text-primary"
185	      >
186	        <X className="h-4 w-4" aria-hidden="true" />
187	      </button>
188	    </header>
189	  );
190	}
191	
192	function MetadataSection({
193	  task,
194	  repository,
195	  nextAction,
196	  lastUpdatedAt,
197	}: {
198	  task: ParsedTask;
199	  repository: string | undefined;
200	  nextAction: string | undefined;
201	  lastUpdatedAt: string | undefined;
202	}) {
203	  return (
204	    <section className="grid grid-cols-2 gap-x-6 gap-y-5 pb-2">
205	      <MetaField icon={<Folder className="h-4 w-4" aria-hidden="true" />} label="Repository">
206	        {repository ? <span className="text-text-primary">{repository}</span> : <NoneValue />}
207	      </MetaField>
208	
209	      <MetaField icon={<GitBranch className="h-4 w-4" aria-hidden="true" />} label="Branch">
210	        {task.branch ? (
211	          <span className="break-all font-mono text-xs text-text-primary">
212	            {task.branch}
213	          </span>
214	        ) : (
215	          <NoneValue />
216	        )}
217	      </MetaField>
218	
219	      <MetaField icon={<ListChecks className="h-4 w-4" aria-hidden="true" />} label="Next Action">
220	        {nextAction ? (
221	          <span className="text-text-primary">{nextAction}</span>
222	        ) : (
223	          <NoneValue />
224	        )}
225	      </MetaField>
226	
227	      <MetaField icon={<User className="h-4 w-4" aria-hidden="true" />} label="Executed By">
228	        <div className="flex flex-col">
229	          <span className="text-text-primary">
230	            {task.execution?.actor_type ?? "—"}
231	          </span>
232	          {lastUpdatedAt ? (
233	            <span className="mt-1 flex items-center gap-1 text-xs text-text-muted">
234	              <Calendar className="h-3 w-3" aria-hidden="true" />
235	              {formatTimestamp(lastUpdatedAt)}
236	            </span>
237	          ) : null}
238	        </div>
239	      </MetaField>
240	
241	      <MetaField label="Depends On" fullWidth>
242	        {task.dependsOn.length > 0 ? (
243	          <div className="flex flex-wrap gap-1.5">
244	            {task.dependsOn.map((dep) => (
245	              <span
246	                key={dep}
247	                className="rounded bg-chip-bg px-2 py-0.5 text-xs font-medium text-text-secondary"
248	              >
249	                {dep}
250	              </span>
251	            ))}
252	          </div>
253	        ) : (
254	          <NoneValue />
255	        )}
256	      </MetaField>
257	
258	      <MetaField
259	        icon={
260	          task.blockedReason ? (
261	            <AlertCircle className="h-4 w-4 text-danger" aria-hidden="true" />
262	          ) : null
263	        }
264	        label="Blocked Reason"
265	        fullWidth
266	      >
267	        {task.blockedReason ? (
268	          <span className="text-text-primary">{task.blockedReason}</span>
269	        ) : (
270	          <NoneValue />
271	        )}
272	      </MetaField>
273	    </section>
274	  );
275	}
276	
277	function MetaField({
278	  icon,
279	  label,
280	  fullWidth,
281	  children,
282	}: {
283	  icon?: React.ReactNode;
284	  label: string;
285	  fullWidth?: boolean;
286	  children: React.ReactNode;
287	}) {
288	  return (
289	    <div className={"flex flex-col gap-1.5 " + (fullWidth ? "col-span-2" : "")}>
290	      <div className="flex items-center gap-1.5 text-xs font-medium uppercase tracking-wide text-text-secondary">
291	        {icon}
292	        <span>{label}</span>
293	      </div>
294	      <div className="text-sm">{children}</div>
295	    </div>
296	  );
297	}
298	
299	function NoneValue() {
300	  return <span className="text-text-muted">None</span>;
301	}
302	
303	function PullRequestsSection({ task }: { task: ParsedTask }) {
304	  const workspacePrUrl = task.workspace_pr?.url ?? undefined;
305	  const workspacePrStatus = task.workspace_pr?.status ?? undefined;
306	  const repoPrUrl = task.pr?.url ?? undefined;
307	  const repoPrStatus = task.pr?.status ?? undefined;
308	
309	  return (
310	    <section className="mt-6 border-t border-border pt-5">
311	      <h3 className="mb-3 text-sm font-semibold text-text-primary">
312	        Pull Requests
313	      </h3>
314	      <div className="flex flex-col gap-2">
315	        <PullRequestCard
316	          label="Workspace PR"
317	          url={workspacePrUrl}
318	          status={workspacePrStatus}
319	        />
320	        <PullRequestCard
321	          label="Repository PR"
322	          url={repoPrUrl}
323	          status={repoPrStatus}
324	        />
325	      </div>
326	    </section>
327	  );
328	}
329	
330	function PullRequestCard({
331	  label,
332	  url,
333	  status,
334	}: {
335	  label: string;
336	  url: string | undefined;
337	  status: string | undefined;
338	}) {
339	  if (!url) {
340	    return (
341	      <div
342	        aria-disabled="true"
343	        className="flex items-center justify-between rounded-lg border border-border bg-muted-bg px-3 py-2.5 opacity-70"
344	      >
345	        <span className="text-sm font-medium text-text-secondary">{label}</span>
346	        <span className="text-xs text-text-muted">None</span>
347	      </div>
348	    );
349	  }
350	
351	  return (
352	    <a
353	      href={url}
354	      target="_blank"
355	      rel="noreferrer noopener"
356	      className="flex items-center justify-between rounded-lg border border-border bg-surface px-3 py-2.5 transition-colors hover:bg-surface-subtle"
357	    >
358	      <div className="flex flex-col">
359	        <span className="text-sm font-medium text-text-primary">{label}</span>
360	        {status ? (
361	          <span className="text-xs text-text-muted">{status}</span>
362	        ) : null}
363	      </div>
364	      <ExternalLink
365	        className="h-4 w-4 text-text-secondary"
366	        aria-hidden="true"
367	      />
368	    </a>
369	  );
370	}
371	
372	function TimelineSection({ log }: { log: LogEntry[] | undefined }) {
373	  return (
374	    <section className="mt-6 border-t border-border pt-5">
375	      <h3 className="mb-3 text-sm font-semibold text-text-primary">
376	        Activity Timeline
377	      </h3>
378	      {log && log.length > 0 ? (
379	        <ol className="flex flex-col gap-3">
380	          {log.map((entry, index) => (
381	            <TimelineEntry
382	              key={`${entry.at}-${index}`}
383	              entry={entry}
384	              isLast={index === log.length - 1}
385	            />
386	          ))}
387	        </ol>
388	      ) : (
389	        <p className="text-sm text-text-muted">No activity logs available.</p>
390	      )}
391	    </section>
392	  );
393	}
394	
395	function TimelineEntry({
396	  entry,
397	  isLast,
398	}: {
399	  entry: LogEntry;
400	  isLast: boolean;
401	}) {
402	  const style = getStatusStyle(entry.action);
403	
404	  return (
405	    <li className="flex gap-3">
406	      <div className="flex flex-col items-center pt-1">
407	        <span
408	          className={"h-2 w-2 rounded-full " + style.dot}
409	          aria-hidden="true"
410	        />
411	        {isLast ? null : (
412	          <span className="mt-1 w-px flex-1 bg-border" aria-hidden="true" />
413	        )}
414	      </div>
415	      <div className="flex flex-1 flex-col gap-0.5 pb-3">
416	        <div className="flex items-center justify-between gap-2">
417	          <span className="text-sm font-medium text-text-primary">
418	            {formatStatusLabel(entry.action)}
419	          </span>
420	          <span className="text-xs text-text-muted">
421	            {formatTimestamp(entry.at)}
422	          </span>
423	        </div>
424	        <span className="text-xs text-text-muted">by {entry.by}</span>
425	        {entry.note ? (
426	          <p className="mt-1 text-sm text-text-secondary">{entry.note}</p>
427	        ) : null}
428	      </div>
429	    </li>
430	  );
431	}
