        <ExternalLink
          className="h-3.5 w-3.5 text-text-muted"
          aria-hidden="true"
        />
      </div>
    </a>
  );
}

function TimelineSection({ log }: { log: LogEntry[] | undefined }) {
  return (
    <section className="mt-6 border-t border-border pt-5">
